def general_siso_auto_cloud_dus_reset_with_ecpri_fronthaul_delay_analysis(testing_env: TestingEnv,
                                                                          reset_repetitions: int,
                                                                          max_du_downtime_increase: int,
                                                                          throughputs: Dict = None,
                                                                          ue_network_modes: Dict[str, str] = None):
    """
    Based on:
    QC Test ID: 84951
    QC Test Name: General_SiSo_Auto_KPI_Site_Reset_with_eCPRI_Fronthaul_Delay_Analysis

    Should report to:
    QC Test ID: 84951
    QC Test Name: General_SiSo_Auto_KPI_Site_Reset_with_eCPRI_Fronthaul_Delay_Analysis

    :param testing_env: testing environment prepared for this test case
    :param reset_repetitions: number of DU resets which will be used in calculation of average DU downtime
    :param max_du_downtime_increase: maximum allowed increase of average DU downtime (in seconds) after enabling actEcpriDelayMeasurement
    :param throughputs: throughput and deviation values for each Cell identified by its nrCellIdentity for NR Cells,
                        eutranCellId for LTE Cells, wnCelId for WCDMA Cells;
                        i.e.:
                        {'827736065': {'throughput': {'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec},
                                       'deviation': '90%'}}
                        defaults to None (L3 call will not be performed)
    :param ue_network_modes: UE serial numbers paired with desired network modes;
                             i.e. {'HZQN1876AAK90100042': 'NR_only',
                                   'M6AIKN009217SWX': 'LTE_only'}
                             possible UE network modes: 'NR_only', 'LTE_only', 'NR_LTE';
                             when using more than one UE please make sure that modes you choose are either all
                             with '_only' suffix or all are 'NR_LTE' as it is not yet possible to mix those.
                             this param is mandatory for SA+NSA mode;
                             defaults to None (network mode will not be changed on any UE)
    """
    bts = testing_env.btss[0]
    stopwatch = testing_env.stopwatch
    caller = testing_env.caller
    errors = testing_env.errors
    output_dir_path = testing_env.output_dir_path
    snapshot_dir_path = testing_env.downloads_dir_path
    params_initial_state = {}
    testing_env.variables.set(name='params_initial_state',
                              value=params_initial_state)

    for du in bts.dus:
        try:
            _store_initial_params_values(du, params_initial_state)
            _disable_act_ecpri_delay_measurement(du)
            make_l3_call_on_each_du_cell_if_requested(du=du,
                                                      caller=caller,
                                                      throughputs=throughputs,
                                                      ue_network_modes=ue_network_modes,
                                                      logs_path=output_dir_path,
                                                      errors=errors)
            average_du_downtime_for_disabled_feature = _measure_average_du_downtime_and_check_status_and_delays(du,
                                                                                                                stopwatch,
                                                                                                                reset_repetitions,
                                                                                                                errors,
                                                                                                                feature_enabled=False)
            _enable_act_ecpri_delay_measurement(du)
            make_l3_call_on_each_du_cell_if_requested(du=du,
                                                      caller=caller,
                                                      throughputs=throughputs,
                                                      ue_network_modes=ue_network_modes,
                                                      logs_path=output_dir_path,
                                                      errors=errors)
            average_du_downtime_for_enabled_feature = _measure_average_du_downtime_and_check_status_and_delays(du,
                                                                                                               stopwatch,
                                                                                                               reset_repetitions,
                                                                                                               errors,
                                                                                                               feature_enabled=True)
            _compare_average_du_downtimes(du,
                                          average_du_downtime_for_disabled_feature,
                                          average_du_downtime_for_enabled_feature,
                                          max_du_downtime_increase,
                                          errors)
            _check_rmods_soap_messages_in_snapshot(du, snapshot_dir_path, errors)
            _disable_act_ecpri_delay_measurement(du)
            make_l3_call_on_each_du_cell_if_requested(du=du,
                                                      caller=caller,
                                                      throughputs=throughputs,
                                                      ue_network_modes=ue_network_modes,
                                                      logs_path=output_dir_path,
                                                      errors=errors)
        except ResultError as exc:
            errors.add_from_exception(exc=exc)

    errors.check()


def teardown_for_general_siso_auto_cloud_dus_reset_with_ecpri_fronthaul_delay_analysis(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors
    params_initial_state = testing_env.variables.get(name='params_initial_state')

    for du in bts.dus:
        try:
            du.config.set(dist_name=params_initial_state[du.name]['dist_name'],
                          param=params_initial_state[du.name]['param'],
                          value=params_initial_state[du.name]['value'])
        except ResultError as exc:
            errors.add_from_exception(exc=exc)


@pretty_log
def _store_initial_params_values(du: Du, params_initial_state: Dict[str, Dict[str, str]]):
    dist_name = 'MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1'
    param = 'actEcpriDelayMeasurement'
    params_initial_state[du.name] = {'dist_name': dist_name,
                                     'param': param,
                                     'value': du.config.get(dist_name=dist_name,
                                                            param=param)}


@pretty_log
def _disable_act_ecpri_delay_measurement(du: Du):
    _allow_alarms_related_to_resetting_du(du)
    du.config.set(dist_name='MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
                  param='actEcpriDelayMeasurement',
                  value='false')
    du.check_if_reachable(delay=60,
                          timeout=600)
    du.check_state(state='on_air',
                   timeout=600)
    _disallow_alarms_related_to_resetting_du(du)


@pretty_log
def _enable_act_ecpri_delay_measurement(du: Du):
    _allow_alarms_related_to_resetting_du(du)
    du.config.set(dist_name='MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
                  param='actEcpriDelayMeasurement',
                  value='true')
    du.check_if_reachable(delay=60,
                          timeout=600)
    du.check_state(state='on_air',
                   timeout=600)
    _disallow_alarms_related_to_resetting_du(du)


@pretty_log
def _allow_alarms_related_to_resetting_du(du: Du):
    du.allow_alarm(fault_id='4592',
                   fault_name='BTS Reset Cause')
    du.cu.allow_alarm(fault_id='7104',
                      fault_name='Matching ServedCell not found over F1-C')


@pretty_log
def _disallow_alarms_related_to_resetting_du(du: Du):
    du.disallow_alarm(fault_id='4592',
                      fault_name='BTS Reset Cause')
    du.cu.disallow_alarm(fault_id='7104',
                         fault_name='Matching ServedCell not found over F1-C')


@pretty_log
def _measure_average_du_downtime_and_check_status_and_delays(du: Du, stopwatch: Stopwatch, reset_repetitions: int,
                                                             errors: ErrorHistory, feature_enabled: bool) -> float:
    log_info(f'Measuring average {du.name} downtime after {reset_repetitions} resets with actEcpriDelayMeasurement '
             f'{"enabled" if feature_enabled else "disabled"}', to_console=True)
    du_downtimes = []
    _allow_alarms_related_to_resetting_du(du)

    for reset_repetition in range(1, reset_repetitions + 1):
        log_info(f'Starting {du.name} reset no. {reset_repetition} out of {reset_repetitions}', to_console=True)
        _trigger_du_reset(du)
        _start_measuring_time(stopwatch)
        _wait_until_all_cells_online(du)
        _stop_measuring_time(stopwatch)
        _save_time_measurement(stopwatch, du_downtimes)

        if feature_enabled:
            _check_rmods_sync_status(du, errors)
            _check_ul_and_dl_min_delays(du, errors)

    _disallow_alarms_related_to_resetting_du(du)
    return _calculate_average_du_downtime(du, du_downtimes)


@pretty_log
def _trigger_du_reset(du: Du):
    du.reset()
    du.check_if_unreachable(timeout=60)


@pretty_log
def _start_measuring_time(stopwatch: Stopwatch):
    log_info('Starting time measurement', to_console=True)
    stopwatch.start()


@pretty_log
def _wait_until_all_cells_online(du: Du):
    du.check_if_reachable(delay=30, timeout=300)
    du.cells.check_state_on_all(state='online',
                                timeout=600)


@pretty_log
def _stop_measuring_time(stopwatch: Stopwatch):
    log_info('Stopping time measurement', to_console=True)
    stopwatch.stop()


@pretty_log
def _save_time_measurement(stopwatch: Stopwatch, measurements: List[int]):
    time_measurement = stopwatch.get_elapsed_seconds()
    measurements.append(time_measurement)
    log_info(f'Measured time was {time_measurement}s', to_console=True)


@pretty_log
def _calculate_average_du_downtime(du: Du, du_downtimes: List[int]) -> float:
    if not du_downtimes:
        raise ResultError(f'No {du.name} downtimes were measured, cannot calculate average downtime')

    average_du_downtime = sum(du_downtimes) / len(du_downtimes)
    log_info(f'Average {du.name} downtime after {len(du_downtimes)} resets is {average_du_downtime}s', to_console=True)
    return average_du_downtime


@pretty_log
def _check_rmods_sync_status(du: Du, errors: ErrorHistory):
    clock_managed_objects = du.config.get_many_by_class_names(dist_name='MRBTS-{}/MNL-1/MNLENT-1', class_names=['CLOCK_R'])

    for rmod in du.rmods:
        try:
            _check_rmod_sync_status(du, rmod, clock_managed_objects)
        except ResultError as exc:
            errors.add_from_exception(exc=exc)


@pretty_log
def _check_rmod_sync_status(du: Du, rmod: CloudRmod, clock_managed_objects: Dict):
    log_info(f'Checking sync status of {rmod.name}', to_console=True)
    rmod_sync_status = None
    expected_rmod_sync_status = 'Locked'

    for clock_managed_object_params in clock_managed_objects.values():
        if clock_managed_object_params['targetDN'] == rmod.config_dist_name:
            rmod_sync_status = clock_managed_object_params['syncStatus']
            break

    if not rmod_sync_status:
        raise UnexpectedConfig(f'No matching CLOCK_R Managed Object found for {rmod.name} in {du.name} configuration')

    if rmod_sync_status != expected_rmod_sync_status:
        raise ResultError(f'Sync status of {rmod.name} is not {expected_rmod_sync_status} but {rmod_sync_status} instead')


@pretty_log
def _check_ul_and_dl_min_delays(du: Du, errors: ErrorHistory):
    log_info('Checking dlMinDelay and ulMinDelay params', to_console=True)
    try:
        link_managed_objects = _get_link_managed_objects(du)
        fhlkdly_managed_objects = _get_fhlkdly_managed_objects(du, link_managed_objects)

        for fhlkdly_dist_name, fhlkdly_params in fhlkdly_managed_objects.items():
            dl_min_delay = int(fhlkdly_params['dlMinDelay'])
            ul_min_delay = int(fhlkdly_params['ulMinDelay'])
            _check_if_ul_and_dl_min_delays_are_not_zero(ul_min_delay, dl_min_delay, fhlkdly_dist_name)
            _check_ul_and_dl_min_delays_difference(ul_min_delay, dl_min_delay, fhlkdly_dist_name)
    except ResultError as exc:
        errors.add_from_exception(exc=exc)


@pretty_log
def _get_link_managed_objects(du: Du) -> Dict:
    cablink_managed_objects = du.config.get_many_by_class_names(dist_name='MRBTS-{}/EQM_R-1/HWTOP_R-1', class_names=['CABLINK_R'])
    loglink_managed_objects = du.config.get_many_by_class_names(dist_name='MRBTS-{}/EQM_R-1/HWTOP_R-1', class_names=['LOGLINK_R'])
    link_managed_objects = {**cablink_managed_objects, **loglink_managed_objects}

    if not link_managed_objects:
        raise UnexpectedConfig(f'No CABLINK_R nor LOGLINK_R Managed Objects found in {du.name} configuration')

    return link_managed_objects


@pretty_log
def _get_fhlkdly_managed_objects(du: Du, link_managed_objects: Dict) -> Dict:
    link_dist_names = list(link_managed_objects.keys())
    fhlkdly_managed_objects = {}

    for link_dist_name in link_dist_names:
        fhlkdly_managed_objects.update(du.config.get_many_by_class_names(dist_name=link_dist_name, class_names=['FHLKDLY_R']))

    if not fhlkdly_managed_objects:
        raise UnexpectedConfig(f'No FHLKDLY_R Managed Objects found in {du.name} configuration')

    return fhlkdly_managed_objects


@pretty_log
def _check_if_ul_and_dl_min_delays_are_not_zero(ul_min_delay: int, dl_min_delay: int, fhlkdly_dist_name: str):
    if dl_min_delay == 0 or ul_min_delay == 0:
        raise UnexpectedConfig(f'Minimum delays for {fhlkdly_dist_name} (dlMinDelay={dl_min_delay}, ulMinDelay={ul_min_delay}) cannot be 0')


@pretty_log
def _check_ul_and_dl_min_delays_difference(ul_min_delay: int, dl_min_delay: int, fhlkdly_dist_name: str):
    if abs(dl_min_delay - ul_min_delay) >= 500:
        raise UnexpectedConfig(f'Difference between minimum delays for {fhlkdly_dist_name} '
                               f'(dlMinDelay={dl_min_delay}, ulMinDelay={ul_min_delay}) cannot be 500 or more')


@pretty_log
def _compare_average_du_downtimes(du: Du,
                                  average_du_downtime_for_disabled_feature: float,
                                  average_du_downtime_for_enabled_feature: float,
                                  max_du_downtime_increase: int,
                                  errors: ErrorHistory):
    log_info(f'Comparing average {du.name} downtimes', to_console=True)
    try:
        check_if_second_measurement_is_higher(first=average_du_downtime_for_disabled_feature,
                                              second=average_du_downtime_for_enabled_feature,
                                              min_delta=0,
                                              max_delta=max_du_downtime_increase)
    except ResultError as exc:
        errors.add_from_exception(exc=exc)


@pretty_log
def _check_rmods_soap_messages_in_snapshot(du: Du, snapshot_dir_path: str, errors: ErrorHistory):
    snapshot_file_path = du.collect_snapshot(path=snapshot_dir_path)
    snapshot = Snapshot()
    snapshot_dir, snapshot_file_name = snapshot_file_path.rsplit('/', maxsplit=1)
    snapshot.set_snapshot_dir(snapshot_dir=snapshot_dir)
    snapshot.set_snapshot_file_name(snapshot_file_name=snapshot_file_name)
    snapshot.set_snapshot_tmp_extract_dir(snapshot_tmp_extract_dir=f'{snapshot_dir}/extracted')

    for rmod in du.rmods:
        try:
            _check_rmod_soap_messages_in_snapshot(du, rmod, snapshot)
        except ResultError as exc:
            errors.add_from_exception(exc=exc)


@pretty_log
def _check_rmod_soap_messages_in_snapshot(du: Du, rmod: CloudRmod, snapshot: Snapshot):
    log_info(f'Checking {rmod.name} SOAP messages in {du.name} snapshot', to_console=True)
    xml_file_path = _get_xml_file_path(du, rmod, snapshot)
    extracted_xml_file_path = _extract_xml_file(du, rmod, snapshot, xml_file_path)
    _check_soap_messages_in_xml_file(du, rmod, extracted_xml_file_path)


@pretty_log
def _get_xml_file_path(du: Du, rmod: CloudRmod, snapshot: Snapshot) -> str:
    xml_file_path = snapshot.find_file_in_snapshot_file_list(filename=f'.*_{rmod.serial_number}_.*_SOAPCFG.xml.gz',
                                                             raise_exception=False)
    if not xml_file_path:
        xml_file_path = snapshot.find_file_in_snapshot_file_list(filename=f'.*_{rmod.serial_number}_.*_SOAPMessageTraceCFG.xml.gz',
                                                                 raise_exception=False)
    if not xml_file_path:
        raise ResultError(f'No XML file with SOAP messages found in {du.name} snapshot for {rmod.name}')

    return xml_file_path


@pretty_log
def _extract_xml_file(du: Du, rmod: CloudRmod, snapshot: Snapshot, xml_file_path: str) -> str:
    error_msg = f'Failed to extract XML file with SOAP messages {xml_file_path} from {du.name} snapshot for {rmod.name}'
    extraction_dir = snapshot.extract_shapshot_file_based_on_internal_path(internal_snapshot_path=xml_file_path,
                                                                           raise_exception=False)
    if not extraction_dir:
        raise ResultError(error_msg)

    xml_archive_name = xml_file_path.rsplit('/', maxsplit=1)[-1]
    xml_archive_path = f'{extraction_dir}/{xml_archive_name}'

    try:
        extracted_xml_file_path = extract_all_archives_from_path(regex_path=xml_archive_path)
    except NameError:
        raise ResultError(error_msg)

    return extracted_xml_file_path


@pretty_log
def _check_soap_messages_in_xml_file(du: Du, rmod: CloudRmod, xml_file_path: str):
    log_debug(f'Checking whether XML file {xml_file_path} from {du.name} snapshot contains expected SOAP messages for {rmod.name}')

    if not all([is_message_in_file(soap_path=xml_file_path,
                                   dist_name='.*',
                                   class_name='SupportedFeature',
                                   content=['<parameterName>feature</parameterName>',
                                            '<newValue>ECPRI_MSG5_DELAY_MEASUREMENT</newValue>',
                                            '<parameterName>support</parameterName>',
                                            '<newValue>9</newValue>']),
                is_message_in_file(soap_path=xml_file_path,
                                   dist_name='.*',
                                   class_name='ECpriDelayMeasurementSession',
                                   content=['<operation>create_mo</operation>']),
                is_message_in_file(soap_path=xml_file_path,
                                   dist_name='.*',
                                   class_name='ECpriDelayMeasurementSession',
                                   content=['<operation>create_mo</operation>',
                                            '<parameterName>subscribe</parameterName>',
                                            '<newValue>TRUE</newValue>'])]):
        raise ResultError(f'Not all expected SOAP messages for {rmod.name} are present in XML file {xml_file_path} from {du.name} snapshot')
